import{_ as t,o,c as s,a2 as a}from"./chunks/framework.B_GyVC5q.js";const f=JSON.parse('{"title":"Trusted folders","description":"","frontmatter":{"title":"Trusted folders"},"headers":[],"relativePath":"guide/trusted-folders.md","filePath":"guide/trusted-folders.md"}'),r={name:"guide/trusted-folders.md"};function n(i,e,l,d,p,c){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="trusted-folders" tabindex="-1">Trusted folders <a class="header-anchor" href="#trusted-folders" aria-label="Permalink to &quot;Trusted folders&quot;">​</a></h1><p>Desktop and mobile only. Allowlist local folders so HTTP Client, entity image/blob fields, and Anonymize can feed 4D <code>$upload</code> with a <strong>random</strong> or <strong>specific</strong> file. This is the <strong>Files editor</strong> (<a href="/4d-dataexplorer/guide/parts.html#files">named parts</a>).</p><p>Open it from the Status bar <strong>Files</strong> control, the command palette (<strong>Trusted folders</strong>), or the mobile Tools menu.</p><p>Folders are stored on this device (alias + absolute path). They are not part of profile export.</p><p>Paths must live under Home, Desktop, Documents, or Downloads (the native filesystem scope). Removing a folder from the list asks for confirmation and only drops the alias — files on disk are not deleted.</p><h2 id="template-syntax" tabindex="-1">Template syntax <a class="header-anchor" href="#template-syntax" aria-label="Permalink to &quot;Template syntax&quot;">​</a></h2><p><code>$files</code> is <strong>file-valued</strong>. It is resolved only when sending a binary / form-data body or uploading an image/blob — not as a string in URLs or JSON.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{$files.photos}}</span></span>
<span class="line"><span>{{$files.photos | ext:jpg,png,webp}}</span></span>
<span class="line"><span>{{$files.photos | recursive:false}}</span></span>
<span class="line"><span>{{$files.photos/cat.jpg}}</span></span>
<span class="line"><span>{{$files.photos/sub/cat.jpg}}</span></span>
<span class="line"><span>{{$files.photos/**/*.png}}</span></span>
<span class="line"><span>{{$files.photos/Black/*.png}}</span></span></code></pre></div><ul><li><code>{{$files.alias}}</code> — random file from that folder</li><li><code>{{$files.alias/relative/path.jpg}}</code> — a specific file (use <code>/</code> because filenames contain dots)</li><li><code>{{$files.alias/**/*.png}}</code> — random file matching a glob (<code>*</code> one segment, <code>**</code> any depth)</li><li><code>| ext:</code> — restrict a random pick by extension</li><li><code>| recursive:false</code> — only the folder’s top level</li></ul><p>Relative paths cannot contain <code>..</code> or start with an absolute drive / root.</p><h2 id="file-manager" tabindex="-1">File manager <a class="header-anchor" href="#file-manager" aria-label="Permalink to &quot;File manager&quot;">​</a></h2><p>The editor has a folder list, an explorer, and a preview pane (wide screens). Sidebar width, preview width, list vs icons, the selected folder, expanded tree paths, and the current file persist on this device.</p><p>Flows <strong>Open</strong> / <strong>Save to trusted folder</strong> reuse the same picker without the preview pane, with a file-type menu (<strong>JSON</strong> or <strong>All files</strong>). Other pickers can keep preview and pass their own extensions.</p><ul><li><strong>List</strong> — tree of folders and files</li><li><strong>Icons</strong> — folder contents as a virtualized grid (large folders stay responsive); double-click a folder to open it; use the breadcrumbs to go up. Thumbnails are a fixed height so rows do not overlap. The file type is a muted badge under the name (not overlaid on the image). Long names wrap without splitting the extension</li><li><strong>Preview</strong> — image thumbnail when possible, plus copy actions for <code>$files</code> templates (specific file, type glob, this-folder glob, random)</li></ul><p>Copy buttons use click-to-copy: the tooltip reads <strong>Click to copy</strong>, then <strong>Copied!</strong> after a click.</p><h3 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h3><p>Focus the explorer (or press <strong>↓</strong> from the filter field). <strong>Esc</strong> returns to the filter.</p><table tabindex="0"><thead><tr><th>Key</th><th>List</th><th>Icons</th></tr></thead><tbody><tr><td><strong>↑</strong> / <strong>↓</strong></td><td>Previous / next visible item</td><td>Move up / down by a row</td></tr><tr><td><strong>←</strong> / <strong>→</strong></td><td>Collapse or parent / expand or first child</td><td>Move left / right</td></tr><tr><td><strong>Home</strong> / <strong>End</strong></td><td>First / last visible item</td><td>First / last in the grid</td></tr><tr><td><strong>Enter</strong></td><td>Toggle a folder or select a file (picks the file in the picker)</td><td>Open a folder or pick a file</td></tr><tr><td><strong>Backspace</strong></td><td>—</td><td>Parent folder</td></tr></tbody></table><h2 id="http-client" tabindex="-1">HTTP Client <a class="header-anchor" href="#http-client" aria-label="Permalink to &quot;HTTP Client&quot;">​</a></h2><p>For <code>POST /rest/$upload?$rawPict=true</code> (images) or <code>?$binary=true</code> (other files), set the body to <strong>Binary</strong> and either pick a file or enter a <code>$files</code> template. Form-data file rows accept the same template.</p><p>Saved requests keep the template text so each send can pick a new random file.</p><h2 id="entity-fields-and-anonymize" tabindex="-1">Entity fields and Anonymize <a class="header-anchor" href="#entity-fields-and-anonymize" aria-label="Permalink to &quot;Entity fields and Anonymize&quot;">​</a></h2><p>While editing an image or blob attribute, <strong>From trusted folder</strong> opens the explorer (specific file or random from the folder) and uploads via <code>$upload</code>.</p><p>In Anonymize, set an image field’s template to <code>{{$files.photos}}</code> (or a specific path / glob). The run loads the local file and uploads it instead of fetching a remote Faker image URL.</p><p><a href="/4d-dataexplorer/guide/flows.html">Flows</a> <strong>File</strong> and <strong>CSV import</strong> blocks also read trusted-folder aliases (desktop / mobile). The Flows library can <strong>open</strong> and <strong>save</strong> a flow JSON as a live file inside a trusted folder; later edits auto-save to that file.</p>`,25)])])}const g=t(r,[["render",n]]);export{f as __pageData,g as default};
